"""Count lines, words and characters in a text file."""
import sys


def count(text):
    lines = text.split("\n")
    words = 0
    for line in lines:
        words += len(line.split(" "))
    return len(lines), words, len(text)


def main(path):
    with open(path) as f:
        lines, words, chars = count(f.read())
    print(f"{lines} lines, {words} words, {chars} characters")


if __name__ == "__main__":
    main(sys.argv[1])

