import unittest

from wc import count


class CountTests(unittest.TestCase):
    def test_simple_line(self):
        self.assertEqual(count("hello world")[1], 2)

    def test_blank_line_adds_no_words(self):
        self.assertEqual(count("\n")[1], 0)

    def test_blank_lines_between_words(self):
        self.assertEqual(count("one\n\ntwo\n")[1], 2)

    def test_extra_spaces_between_words(self):
        self.assertEqual(count("the quick    brown fox")[1], 4)

    def test_leading_and_trailing_spaces(self):
        self.assertEqual(count("   spaced out   ")[1], 2)

    def test_line_of_only_spaces(self):
        self.assertEqual(count("   \n   ")[1], 0)

    def test_tabs_and_mixed_whitespace(self):
        self.assertEqual(count("a\tb \t c")[1], 3)

    def test_empty_text(self):
        self.assertEqual(count(""), (1, 0, 0))

    def test_line_and_char_counts_unchanged(self):
        self.assertEqual(count("hello world\n\n  spaced   out  \n"), (4, 4, 30))


if __name__ == "__main__":
    unittest.main()

